// One call for the caller; four collaborators behind it
class AttachmentFacade {
  AttachmentFacade(this._picker, this._permissions, this._compressor, this._uploads);

  final ImagePicker _picker;
  final PermissionService _permissions;
  final ImageCompressor _compressor;
  final UploadRepository _uploads;

  /// Returns null when the user cancels or denies access.
  Future<Attachment?> pickAndUpload({void Function(double)? onProgress}) async {
    if (!await _permissions.ensurePhotos()) return null;

    final picked = await _picker.pickImage(source: ImageSource.gallery);
    if (picked == null) return null;

    final small = await _compressor.toJpeg(File(picked.path), maxWidth: 1600);
    return _uploads.upload(small, onProgress: onProgress);
  }
}

