// ── A builder that earns it: accumulation, then a whole-set check ──
class QueryBuilder {
  final _where = <String>[];
  final _args = <Object?>[];
  String? _orderBy;
  int? _limit;

  QueryBuilder where(String clause, Object? arg) {
    _where.add(clause);
    _args.add(arg);
    return this; // fluent because state accumulates, not for style
  }

  QueryBuilder orderBy(String column) => this.._orderBy = column;
  QueryBuilder limit(int n) => this.._limit = n;

  Query build() {
    if (_limit != null && _orderBy == null) {
      throw StateError('limit without orderBy returns arbitrary rows');
    }
    return Query(_where.join(' AND '), _args, _orderBy, _limit);
  }
}

