class _FeedPageState extends State<FeedPage> with WidgetsBindingObserver {
  late final ScrollController _scroll;
  StreamSubscription<Feed>? _sub;
  Feed? _feed;

  @override
  void initState() {
    super.initState(); // base first: the framework is ready before you are
    _scroll = ScrollController()..addListener(_onScroll);
    WidgetsBinding.instance.addObserver(this);
    _load(); // fire and forget; initState itself must stay synchronous
  }

  Future<void> _load() async {
    final feed = await widget.repository.load(widget.userId);
    if (!mounted) return; // the await outlived the element
    setState(() => _feed = feed);
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _dateFormat = DateFormat.yMMMd(Localizations.localeOf(context).toString());
  }

  @override
  void didUpdateWidget(covariant FeedPage oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.userId != widget.userId) _load(); // only place that sees the old widget
  }

  @override
  void dispose() {
    _sub?.cancel(); // yours first
    _scroll.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose(); // base last, and it asserts you got here
  }
}

