}

// ✅ Symmetric, with the same reference on both sides
class _CartBadgeState extends State<CartBadge> {
  StreamSubscription<Status>? _sub;

  void _onCartChanged() => setState(() {});

  @override
  void initState() {
    super.initState();
    widget.cart.addListener(_onCartChanged); // tear-off: equal across calls
    _sub = connectivity.onStatusChange.listen(_onStatus); // same rule for streams
  }

  @override
  void dispose() {
    widget.cart.removeListener(_onCartChanged);
    _sub?.cancel();
    super.dispose(); // note: no widget.cart.dispose() — you did not create it
  }
}

