sealed class FeedItem {
  const FeedItem();

  factory FeedItem.fromJson(Map<String, dynamic> json) => switch (json['type']) {
        'article' => Article.fromJson(json),
        'poll' => Poll.fromJson(json),
        'ad' => SponsoredAd.fromJson(json),
        final String other => UnknownItem(other), // new server, old client
        _ => const UnknownItem('missing'),
      };
}

final class UnknownItem extends FeedItem {
  const UnknownItem(this.type);
  final String type;
}

// One bad row costs one row, not the whole screen
List<FeedItem> parseFeed(List<dynamic> rows) {
  final out = <FeedItem>[];
  for (final row in rows) {
    try {
      final item = FeedItem.fromJson(row as Map<String, dynamic>);
      if (item is UnknownItem) {
        log.info('skipping unknown feed type ${item.type}');
        continue;
      }
      out.add(item);
    } on Object catch (e, s) {
      log.warning('dropped malformed feed row', e, s);
    }
  }
  return out;
}

