const Object _unset = Object();

class Profile {
  const Profile({required this.id, required this.name, this.avatarUrl});
  final String id;
  final String name;
  final String? avatarUrl;

  // ✅ Sentinel: absent and explicitly null become distinguishable again
  Profile copyWith({Object? name = _unset, Object? avatarUrl = _unset}) => Profile(
        id: id,
        name: identical(name, _unset) ? this.name : name as String,
        avatarUrl: identical(avatarUrl, _unset) ? this.avatarUrl : avatarUrl as String?,
      );
}

