sealed class Node {}

final class Heading extends Node {
  Heading(this.level, this.text);
  final int level;
  final String text;
}

final class Paragraph extends Node {
  Paragraph(this.spans);
  final List<Node> spans;
}

final class CodeBlock extends Node {
  CodeBlock(this.source, this.language);
  final String source;
  final String? language;
}

// Operation 1: render. No accept(), no visitor object, exhaustive by construction.
Widget toWidget(Node node) => switch (node) {
      Heading(:final level, :final text) => Text(text, style: headingStyles[level]),
      Paragraph(:final spans) => Wrap(children: spans.map(toWidget).toList()),
      CodeBlock(:final source, :final language) => CodeView(source, language: language),
    };

// Operation 2: plain text for search. Adding it touched no node class.
String toPlainText(Node node) => switch (node) {
      Heading(:final text) => text,
      Paragraph(:final spans) => spans.map(toPlainText).join(),
      CodeBlock(:final source) => source,
    };

// Add `final class Quote extends Node {}` and BOTH switches stop compiling. That is the point.

// Visitor is the fallback when the hierarchy is not yours to seal
abstract interface class NodeVisitor<R> {
  R visitHeading(Heading node);
  R visitParagraph(Paragraph node);
  R visitCodeBlock(CodeBlock node);
}

